"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";

export function TextMorphTailwind() {
  const words = ["zero-jank layouts", "120Hz spring physics", "Next.js App Router"];
  const [idx, setIdx] = React.useState(0);
  React.useEffect(() => {
    const id = setInterval(() => setIdx((i) => (i + 1) % words.length), 2400);
    return () => clearInterval(id);
  }, []);
  return (
    <div className="inline-flex items-baseline gap-2 text-xl font-semibold text-zinc-400">
      <span>Engineered for</span>
      <AnimatePresence mode="wait">
        <motion.span
          key={words[idx]}
          initial={{ opacity: 0, y: 12, filter: "blur(6px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          exit={{ opacity: 0, y: -12, filter: "blur(6px)" }}
          className="rounded-md border border-zinc-800 bg-zinc-900 px-2.5 py-0.5 text-zinc-100"
        >
          {words[idx]}
        </motion.span>
      </AnimatePresence>
    </div>
  );
}
